// TH15 v1.00b / st05.ecl / MainSub09 (1723-1743) + GirlA07 (635-767).
// Source time 0 = MainSub09 entry; card frame = source frame + OPENING_BUFFER
// (plus new-task startup offset, see report).

const TIME_LIMIT: int = 2224;
const OPENING_BUFFER: int = 120;

// TH15 bullet types used by this card (copy from transcribe/th15/touhou-bullets.ecl).
const TH15_STAR_R: int = 608;   // source type16
const TH15_STAR_L: int = 944;   // source type37

// EX 0x200000 VELTIME, a=60: scalar speed ramps 1.0 -> target in 60 frames,
// angle preserved (s=-999999). Approximated with a polar acceleration ramp.
xformdef VEL_RAMP(target: fx) {
    @60 set_accel((target - 1fx) / 60fx);
    set_accel(0fx);
}

// GirlA07_at2 (707-767): two interleaved rings per burst, 80 bursts, 400 apart.
async sub girl_shot() {
    var rank: int = global(GVAR_RANK);
    var n: int = 8;                         // !E 4; !N 8; !H 8; !LO 11
    if rank == 0 { n = 4; }
    if rank == 3 { n = 11; }
    var target_a: fx = 4fx;                 // !E 2.0; !NHL 4.0
    if rank == 0 { target_a = 2fx; }
    var target_b: fx = 1.1fx;               // !E/N 1.1; !H 1.5; !LO 2.1
    if rank == 2 { target_b = 1.5fx; }
    if rank == 3 { target_b = 2.1fx; }
    var half: angle = (32768 / n) as angle; // mode5 pi/N half-gap

    sh_reset(0);                            // etNew(0); etAim(0,3) fixed ring
    sh_sprite(0, TH15_STAR_L, 13);          // etSprite(0,37,13)
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);                      // etCount(0,[-1],1)
    sh_speed(0, 1fx, 0fx);                  // etSpeed(0,1.0,0.2), one layer
    sh_dist(0, 12fx);                       // etDist(16) plus ANIM entry shift -4*1.0
    sh_xform(0, VEL_RAMP(target_a));

    sh_reset(1);                            // etNew(0); etAim(0,5) half-gap ring
    sh_sprite(1, TH15_STAR_R, 10);          // etSprite(0,16,10)
    sh_ring(1, 1);
    sh_aim(1, 0);
    sh_count(1, n, 1);
    sh_speed(1, 1fx, 0fx);
    sh_dist(1, 12fx);
    sh_xform(1, VEL_RAMP(target_b));

    wait(50 + rand(35));                    // wait(50 + $RAND % 35)
    for i in 0..80 {                        // $B = 80
        var a: angle = rand(65536) as angle;   // %A = %RANDRAD
        sh_angle(0, a, 0deg);
        sh_angle(1, a + half, 0deg);
        sh_fire(0);
        sh_fire(1);
        wait(400);
    }
}

// GirlA07_at (646-664), survival path: the source clears its death callback
// after 60 frames and the shell enemy never dies, so GirlA07_at1 is omitted.
async sub girl(dir: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);                      // setHurtbox(24,24)
    set_hitbox(8fx);                        // setHitbox(16,16)
    spawn girl_shot();                      // @GirlA07_at2() async
    move_vel(0, dir, 4fx, EASE_LINEAR);                  // moveVel(%F0,4.0)
    move_vel(120, 90deg, 2fx, EASE_QUAD_IN);             // moveVelTime(120,1,pi/2,2.0)
    wait(120);                                           // wait(60); wait(60)
    move_vel(60, dir, 6fx, EASE_QUAD_OUT);               // moveVelTime(60,4,%F0,6.0)
    loop { wait(1000); }                                 // GirlA07_at_324/344
}

// MainSub09 (1723-1743): 65 paired spawns, 10 frames between them,
// A starts at 16 and advances by 28 mod 192 after each pair.
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(80);
    var a: int = 16;
    for k in 0..65 {
        var r1: int = rand(65536) - 32768;               // RANDF2 in [-1,1)
        var d1: angle = 90deg + ((r1 * 3641) / 32768) as angle;
        _ = spawn_enemy(a as fx, -32fx, 50, 0, 1000, 0, girl(d1));
        wait(10);
        var r2: int = rand(65536) - 32768;
        var d2: angle = 90deg + ((r2 * 3641) / 32768) as angle;
        _ = spawn_enemy((0 - a) as fx, -32fx, 50, 0, 1000, 0, girl(d2));
        a = (a + 28) % 192;
        wait(10);
    }
    wait(70);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
